import argparse

def get_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--exp_name', action = 'store', type = str, required = True, dest = 'exp_name')
    parser.add_argument('--indices', action = 'store', nargs = '*', type = int, dest = 'indices')
    parser.add_argument('--setting', action = 'store', type = str, dest = 'setting', default = 'imagenet', choices = ['imagenet', 'cifar', 'text', 'embedding'])
    parser.add_argument('--model', action = 'store', type = str, dest = 'model', default = None)
    parser.add_argument('--target_type', action = 'store', type = str, dest = 'target_type', default = 'conv')
    parser.add_argument('--replace', action = 'store', type = str, dest = 'replacement_type', default = 'independent', choices = ['independent', 'sequential',
                                                                                                                                  'joint', 'progressive',
                                                                                                                                  'progressive_align_resnet',
                                                                                                                                  'progressive_align_gpt2s',
                                                                                                                                  'progressive_align_berts',
                                                                                                                                  'progressive_align_rnn_to_rn18',
                                                                                                                                  'progressive_align_vits',
                                                                                                                                  'progressive_align_cnxv2'])

    parser.add_argument('--data_dir', action = 'store', type = str, dest = 'data_dir', default = '../../imagenet_pytorch')
    parser.add_argument('--seed', action = 'store', type = int, dest = 'seed', default = 0)
    parser.add_argument('--imagenet', action = 'store', type = str, dest = 'imagenet', default = 'imagenet-1k')
    parser.add_argument('--seq_len', action = 'store', type = int, default = 1024, dest = 'seq_len')
    parser.add_argument('--num_workers', action = 'store', type = int, default = 32, dest = 'num_workers')
    parser.add_argument('--full_rank', action = 'store_false', dest = 'low_rank')
    parser.add_argument('--rank', action = 'store', type = int, dest = 'rank', default = 1024)
    parser.add_argument('--ranks', nargs='+', type=int, default = None)
    parser.add_argument('--svd_init', action = 'store_true', dest = 'svd_init')
    parser.add_argument('--mixup_alpha', action = 'store', type = float, dest = 'mixup_alpha', default = 0.0)
    parser.add_argument('--train_context_blocks', action = 'store', type = int, dest = 'train_context_blocks', default = 0)

    parser.add_argument('--repdist', action = 'store', type = str, dest = 'repdist', default = 'CKA', choices = ['CKA', 'Procrustes', 'MSE', 'KNN', 'UCKA'])
    parser.add_argument('--rep_lr', action = 'store', type = float, dest = 'rep_lr', default = 1e-2)
    parser.add_argument('--rep_epochs', action = 'store', type = int, dest = 'rep_epochs', default = 10)
    parser.add_argument('--rep_batch', action = 'store', type = int, dest = 'rep_batch', default = 256)
    parser.add_argument('--rep_wd', action = 'store', type = float, dest = 'rep_wd', default = 1e-4)
    parser.add_argument('--rep_agg', action = 'store', type = str, dest = 'rep_agg', default = 'mean', choices = ['mean', 'sum'])
    parser.add_argument('--knn_temp', action = 'store', type = float, dest = 'knn_temp', default = 1.0)
    parser.add_argument('--knn_k', action = 'store', type = int, dest = 'knn_k', default = 10)
    parser.add_argument('--cka_loss', action = 'store', type = str, dest = 'cka_loss', default = 'log', choices = ['normal', 'log', 'fancy', 'token_cka', 'debiased'])
    parser.add_argument('--knn_loss', action = 'store', type = str, dest = 'knn_loss', default = 'normal', choices = ['normal', 'token_knn', 'soft'])
    parser.add_argument('--knn_neg_w', action = 'store', type = float, dest = 'knn_neg_w', default = 1.0)
    parser.add_argument('--distillation', action = 'store_true', dest = 'distillation')
    parser.add_argument('--distil_temp', action = 'store', type = int, dest = 'distil_temp', default = 4)
    parser.add_argument('--distil_alpha', action = 'store', type = float, dest = 'distil_alpha', default = 0.5)
    parser.add_argument('--progressive_lrs', action = 'store', nargs = '*', default = [1e-3], type = float)
    parser.add_argument('--progressive_epochs', action = 'store', nargs = '*', default = [10], type = int)
    parser.add_argument('--reload_progressive', action = 'store_true', dest = 'reload_progressive')
    parser.add_argument('--prog_ckpt', action = 'store', type = str, dest = 'prog_ckpt', default = 'replace_progressive_3_0')
    parser.add_argument('--task_penalty', action = 'store', type = float, dest = 'task_penalty', default = 0.1)
    parser.add_argument('--bit8_adam', action = 'store_true', dest = 'bit8_adam')
    parser.add_argument('--skip_indiv', action = 'store_true', dest = 'skip_indiv')
    parser.add_argument('--teacher_start_weight', action = 'store', type = float, dest = 'teacher_start_weight', default = 0.25)
    parser.add_argument('--preserve_alignment', action = 'store_true', dest = 'preserve_alignment')
    parser.add_argument('--measure_alignment', action = 'store_true', dest = 'measure_alignment')
    parser.add_argument('--rep_sim_weight', action = 'store', type = float, dest = 'rep_sim_weight', default = 0.01)
    
    parser.add_argument('--ft_batch', action = 'store', type = int, dest = 'ft_batch', default = 256)
    parser.add_argument('--ft_lr', action = 'store', type = float, dest = 'ft_lr', default = 1e-4)
    parser.add_argument('--ft_wd', action = 'store', type = float, dest = 'ft_wd', default = 1e-2)
    parser.add_argument('--ft_epochs', action = 'store', type = int, dest = 'ft_epochs', default = 50)
    parser.add_argument('--ft_eval', action = 'store', type = str, dest = 'evaluate', choices = ['steps', 'epoch'], default = 'epoch')
    parser.add_argument('--ft_eval_steps', action = 'store', type = int, dest = 'eval_steps', default = 500)
    parser.add_argument('--warmup_epochs', action = 'store', type = int, dest = 'warmup_epochs', default = 5)
    parser.add_argument('--flat_epochs', action = 'store', type = int, dest = 'flat_epochs', default = 20)
    parser.add_argument('--scheduler_type', action = 'store', type = str, dest = 'scheduler_type', choices = ['cosine', 'plateau', 'onecycle', 'cosine_flat'], default = 'cosine')
    parser.add_argument('--accumulation', action = 'store', type = int, dest = 'accumulation', default = 1)
    parser.add_argument('--ft_optimizer', action = 'store', dest = 'ft_optimizer', default = 'adamw')
    parser.add_argument('--ft_accum', action = 'store', type = int, default = 1, dest = 'ft_accum')
    parser.add_argument('--label_smoothing', action = 'store', type = float, default = 0.0, dest = 'label_smoothing')
    parser.add_argument('--anchor_to_init', action = 'store_true', dest = 'anchor_to_init')
    parser.add_argument('--anchor_lambda', action = 'store', type = float, dest = 'anchor_lambda', default = 0.1)
    parser.add_argument('--compare_weights', action = 'store_true', dest = 'compare_weights')

    parser.add_argument('--supervise_blocks', action = 'store_false', dest = 'supervise_blocks')
    parser.add_argument('--resnet_anchor', action = 'store', type = str, dest = 'resnet_anchor', default = 'mid', 
                        choices = ['early', 'mid', 'late'])
    parser.add_argument('--like_convs', action = 'store_true', dest = 'like_convs')

    parser.add_argument('--joint_rn', action = 'store_true', dest = 'joint_rn')
    parser.add_argument('--joint_vit', action = 'store_true', dest = 'joint_vit')
    parser.add_argument('--joint_cnxv2', action = 'store_true', dest = 'joint_cnxv2')

    parser.add_argument('--layer_weight', action = 'store_true', dest = 'layer_weight')
    parser.add_argument('--token_avg', action = 'store_true', dest = 'token_avg')
    parser.add_argument('--tune_linear', action = 'store_true', dest = 'tune_linear')
    parser.add_argument('--fc_only', action = 'store_true', dest = 'fc_only')
    parser.add_argument('--continue_rep', action = 'store_true', dest = 'continue_rep')
    parser.add_argument('--tune_rnn', action = 'store_true', dest = 'tune_rnn')
    parser.add_argument('--use_amp', action = 'store_true', dest = 'use_amp')
    parser.add_argument('--reload_cka', action = 'store_true', dest = 'reload_cka')
    parser.add_argument('--reload_cka_model', action = 'store', type = str, dest = 'reload_cka_model', default = 'replace_6_7_8_9_10_11_12_13_14_15_16_17_18_19_20')
    parser.add_argument('--post_activation', action = 'store_true', dest = 'post_activation')
    parser.add_argument('--reload_ft', action = 'store_true', dest = 'reload_ft')
    parser.add_argument('--rep_scheduler', action = 'store_true', dest = 'rep_scheduler')
    parser.add_argument('--scheduler', action = 'store_true', dest = 'use_scheduler')
    parser.add_argument('--untrained', action = 'store_false', dest = 'pretrained')
    parser.add_argument('--task_loss', action = 'store_true', dest = 'task_loss')
    parser.add_argument('--local_loss', action = 'store_true', dest = 'local_loss')
    parser.add_argument('--replace_norm', action = 'store_true', dest = 'replace_norm')
    parser.add_argument('--baseline', action = 'store_true', dest = 'baseline')
    parser.add_argument('--continue_ft', action = 'store_true', dest = 'continue_ft')
    parser.add_argument('--compute_norms', action = 'store_true', dest = 'compute_norms')
    parser.add_argument('--reshape_tokens', action = 'store_true', dest = 'reshape_tokens')
    parser.add_argument('--log_hsic', action = 'store_true', dest = 'log_hsic')
    parser.add_argument('--ft_clip', action = 'store', type = float, dest = 'ft_clip', default = 1.0)
    parser.add_argument('--log_cosine', action = 'store_true', dest = 'log_cosine')
    parser.add_argument('--weighting_strategy', action = 'store', type = str, dest = 'weighting_strategy', default = 'complicated', choices = ['simple', 'complicated'])
    parser.add_argument('--like_vit', action = 'store_true', dest = 'like_vit')
    parser.add_argument('--student_vit', action = 'store', type = str, dest = 'student_vit', default = 'vit_tiny', 
                        choices = ['vit_tiny', 'vit_small', 'vit_base', 'vit_large'])
    parser.add_argument('--student_cnxv2', action = 'store', type = str, dest = 'student_cnxv2', default = 'cnx2_atto', 
                        choices = ['cnx2_atto', 'cnx2_femto', 'cnx2_pico', 'cnx2_nano', 'cnx2_tiny', 'cnx2_base', 'cnx2_large'])
    parser.add_argument('--student_gpt2', action = 'store', type = str, dest = 'student_gpt2', default = 'gpt2_tiny', 
                        choices = ['gpt2_tiny', 'gpt2_small', 'gpt2', 'gpt2-large']) 
    parser.add_argument('--student_bert', action = 'store', type = str, dest = 'student_bert', default = 'bert-base', 
                        choices = ['bert-base', 'bert-large'])
    parser.add_argument('--bert_anchor', action = 'store', type = str, dest = 'bert_anchor', default = 'late', choices = ['early', 'mid', 'late'])
    parser.add_argument('--joint_bert', action = 'store_true', dest = 'joint_bert')
    parser.add_argument('--bert_no_pooler', action = 'store_false', dest = 'include_bert_pooler')
    parser.add_argument('--bert_tokenizer', action = 'store', type = str, dest = 'bert_tokenizer', default = 'bert-base-uncased')
    parser.add_argument('--embedding_dataset', action = 'store', type = str, dest = 'embedding_dataset', default = 'sentence-transformers/msmarco-msmarco-MiniLM-L6-v3')
    parser.add_argument('--embedding_dataset_config', action = 'store', type = str, dest = 'embedding_dataset_config', default = 'auto')
    parser.add_argument('--embedding_train_split', action = 'store', type = str, dest = 'embedding_train_split', default = 'train')
    parser.add_argument('--embedding_val_split', action = 'store', type = str, dest = 'embedding_val_split', default = None)
    parser.add_argument('--embedding_val_fraction', action = 'store', type = float, dest = 'embedding_val_fraction', default = 0.01)
    parser.add_argument('--embedding_max_train_samples', action = 'store', type = int, dest = 'embedding_max_train_samples', default = None)
    parser.add_argument('--embedding_max_val_samples', action = 'store', type = int, dest = 'embedding_max_val_samples', default = 4096)
    parser.add_argument('--query_max_len', action = 'store', type = int, dest = 'query_max_len', default = 32)
    parser.add_argument('--passage_max_len', action = 'store', type = int, dest = 'passage_max_len', default = 192)
    parser.add_argument('--embedding_pool', action = 'store', type = str, dest = 'embedding_pool', default = 'cls', choices = ['cls', 'mean'])
    parser.add_argument('--embedding_temperature', action = 'store', type = float, dest = 'embedding_temperature', default = 0.05)
    parser.add_argument('--embedding_use_hard_negatives', action = 'store_true', dest = 'embedding_use_hard_negatives')
    parser.add_argument('--embedding_negatives_per_query', action = 'store', type = int, dest = 'embedding_negatives_per_query', default = 1)
    parser.add_argument('--embedding_streaming_train_samples', action = 'store', type = int, dest = 'embedding_streaming_train_samples', default = 100000)
    parser.add_argument('--rep_val_interval', action = 'store', type = int, dest = 'rep_val_interval', default = 50)
    parser.add_argument('--max_stage_steps', action = 'store', type = int, dest = 'max_stage_steps', default = None)
    parser.add_argument('--align_mix', action = 'store', type = float, dest = 'align_mix', default = 1.0)
    parser.add_argument('--pool_hw', action = 'store', type = int, dest = 'pool_hw', default = 0)
    parser.add_argument('--vit_endonly', action = 'store_true', dest = 'vit_endonly')
    parser.add_argument('--freeze_bn_stats_align', action = 'store_true', dest = 'freeze_bn_stats_align')
    parser.add_argument('--vit_branch_end', action = 'store_true', dest = 'vit_branch_end')
    parser.add_argument('--cnxv2_branch_end', action = 'store_true', dest = 'cnxv2_branch_end')
    parser.add_argument('--optimization_prior', action = 'store_true')
    parser.add_argument('--align_only', action = 'store_true')
    parser.add_argument('--teacher_seed', type = int, default = 1000)
    parser.add_argument('--teacher_depth', type = int, default = None)
    parser.add_argument('--rep_val_size', type = int, default = 4096)
    parser.add_argument('--rep_split_seed', type = int, default = 0)
    parser.add_argument('--prior_norm', choices = ['batch', 'eval'], default = 'batch')
    parser.add_argument('--prior_descriptor', choices = ['pooled', 'spatial'], default = 'pooled')
    parser.add_argument('--prior_schedule', choices = ['cumulative', 'frozen'], default = 'cumulative')
    parser.add_argument('--prior_start_stage', type = int, default = 1)
    parser.add_argument('--prior_update_scope', choices = ['prefix', 'suffix'], default = 'prefix')
    parser.add_argument('--prior_min_rank_ratio', type = float, default = 0.0)
    parser.set_defaults(low_rank = True, tune_linear = False, reload_cka = False, reload_ft = False, scheduler = False, pretrained = True, 
                        task_loss = False, rep_scheduler = False, reload_progressive = False, svd_init = False, post_activation = False,
                        layer_weight = False, replace_norm = False, baseline = False, tune_rnn = False, use_amp = False, continue_rep = False,
                        compute_norms = False, token_avg = False, reshape_tokens = False, log_hsic = False, fc_only = False, bit8_adam = False, 
                        skip_indiv = False, continue_ft = False, log_cosine = False, compare_weights = False, preserve_alignment = False,
                        measure_alignment = False, supervise_blocks = True, like_convs = False, joint_rn = False, joint_vit = False, joint_bert = False, embedding_use_hard_negatives = False, include_bert_pooler = True, 
                        vit_endonly = False, freeze_bn_stats_align = False, vit_branch_end = False, cnxv2_branch_end = False)
    args = parser.parse_args()
    return args